package com.johnny.hotel.cms;
import com.johnny.hotel.cms.CmsModels.*;import com.johnny.hotel.entity.SysAuditLog;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.mapper.SysAuditLogMapper;import com.johnny.hotel.pagination.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.web.multipart.MultipartFile;import tools.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;
@Service@RequiredArgsConstructor public class CmsService{private static final Set<String>LOCALES=Set.of("zh-CN","en"),SECTIONS=Set.of("HERO","TEXT","IMAGE","GALLERY","VIDEO","PROMOTION_LIST","ROOM_TYPE_SHOWCASE","MODEL_SCENE","LOCATION","CTA","CUSTOM_STRUCTURED"),TARGETS=Set.of("INTERNAL_PAGE","EXTERNAL_URL","BOOKING","CUSTOMER_ACCOUNT");private final CmsMapper db;private final CmsAccess access;private final PaginationSupport pages;private final SysAuditLogMapper audits;private final MediaStorageService storage;private final Clock clock;private final ObjectMapper json;
 private void need(boolean x,String m){if(!x)throw new BusinessException(m);}private String locale(String x){need(LOCALES.contains(x),"Unsupported locale");return x;}private String text(String x){return x==null?null:x.trim();}private void audit(Long a,String action,String detail){need(audits.insert(SysAuditLog.builder().operatorId(a).action(action).detail(detail).build())==1,"Audit failed");}private void validJson(String x){try{var n=json.readTree(x);need(n!=null&&!n.isTextual(),"Structured JSON required");String s=x.toLowerCase(Locale.ROOT);need(!s.contains("<script")&&!s.contains("javascript:"),"Unsafe content");}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException("Invalid JSON payload");}}private void publicPayload(String x){validJson(x);String s=x.toLowerCase(Locale.ROOT);for(String key:List.of("\"roomid\"","\"nodekey\"","\"bindings\"","\"stayid\"","\"workorder"))need(!s.contains(key),"Internal fields are forbidden in public content");}
 @Transactional public PageView create(CmsRequests.PageCreate r){Long a=access.writer();locale(r.getLocale());var p=Page.builder().slug(r.getSlug().trim().toLowerCase(Locale.ROOT)).locale(r.getLocale()).createdBy(a).build();need(p.getSlug().matches("[a-z0-9][a-z0-9-]{0,119}"),"Invalid slug");need(db.insertPage(p)==1,"Page creation failed");var v=PageVersion.builder().pageId(p.getId()).versionNo(1).status("DRAFT").title(r.getTitle().trim()).seoTitle(text(r.getSeoTitle())).seoDescription(text(r.getSeoDescription())).socialPreviewMediaId(r.getSocialPreviewMediaId()).createdBy(a).updatedBy(a).build();need(db.insertVersion(v)==1,"Draft creation failed");audit(a,"CMS_PAGE_CREATED","Page "+p.getId());return view(p,v);}
 @Transactional public PageView edit(Long id,CmsRequests.PageEdit r){Long a=access.writer();var p=db.lockPage(id);need(p!=null,"Page not found");var v=draftOrClone(p,a);need(v.getVersionNo().equals(r.getExpectedVersion()),"Draft version changed");v.setTitle(r.getTitle().trim());v.setSeoTitle(text(r.getSeoTitle()));v.setSeoDescription(text(r.getSeoDescription()));v.setSocialPreviewMediaId(r.getSocialPreviewMediaId());v.setUpdatedBy(a);need(db.updateDraft(v)==1,"Draft changed concurrently");audit(a,"CMS_PAGE_UPDATED","Page "+id);return view(p,db.draft(id));}
 @Transactional public Section section(Long page,CmsRequests.SectionWrite r,Long section){Long a=access.writer();var p=db.lockPage(page);need(p!=null,"Page not found");var v=draftOrClone(p,a);need(SECTIONS.contains(r.getSectionType()),"Invalid section type");String visibility=Optional.ofNullable(r.getVisibility()).orElse("PUBLIC");need(Set.of("PUBLIC","INTERNAL").contains(visibility),"Invalid visibility");if("PUBLIC".equals(visibility))publicPayload(r.getPayload());else validJson(r.getPayload());var s=Section.builder().id(section).pageVersionId(v.getId()).sectionKey(r.getSectionKey().trim()).sectionType(r.getSectionType()).sortOrder(r.getSortOrder()).payload(r.getPayload()).visibility(visibility).status("ACTIVE").version(r.getExpectedVersion()).build();if(section==null)need(db.insertSection(s)==1,"Section creation failed");else need(db.updateSection(s)==1,"Section changed concurrently");audit(a,section==null?"CMS_SECTION_CREATED":"CMS_SECTION_UPDATED","Page "+page);return s;}
 @Transactional public void deleteSection(Long page,Long id){Long a=access.writer();var p=db.lockPage(page);need(p!=null,"Page not found");var v=draftOrClone(p,a);need(db.deleteSection(id,v.getId())==1,"Section not found");audit(a,"CMS_SECTION_DELETED","Page "+page);}
 @Transactional public PageView reorder(Long page,CmsRequests.Reorder r){Long a=access.writer();var p=db.lockPage(page);need(p!=null,"Page not found");var v=draftOrClone(p,a);int n=0;for(Long id:r.getSectionIds())need(db.reorder(id,v.getId(),n++)==1,"Invalid section order");audit(a,"CMS_SECTIONS_REORDERED","Page "+page);return view(p,v);}
 @Transactional public PageView publish(Long page){Long a=access.writer();var p=db.lockPage(page);need(p!=null,"Page not found");var v=db.draft(page);need(v!=null,"No draft to publish");db.archivePublished(page,a);need(db.publish(v.getId(),a,LocalDateTime.now(clock))==1,"Publish changed concurrently");audit(a,"CMS_PAGE_PUBLISHED","Page "+page+" version "+v.getVersionNo());return view(p,db.published(page));}
 @Transactional public void unpublish(Long page){Long a=access.writer();var p=db.lockPage(page);need(p!=null,"Page not found");var v=db.published(page);need(v!=null&&db.unpublish(v.getId(),a)==1,"Published page not found");audit(a,"CMS_PAGE_UNPUBLISHED","Page "+page);}
 public PageView preview(Long page){access.writer();var p=db.page(page);need(p!=null,"Page not found");var v=db.draft(page);if(v==null)v=db.published(page);need(v!=null,"Page version not found");return view(p,v);}public PageResult<Page> pages(String locale,String q,Integer page,Integer size){access.writer();if(locale!=null)locale(locale);q=q==null||q.isBlank()?null:q.trim();var w=pages.window(page,size,locale!=null||q!=null);return pages.result(w,db.pages(locale,q,w.offset(),pages.limit(w)),db.pageCount(locale,q));}
 public PublicPage publicPage(String slug,String requested){var found=findPublic(slug,requested);if(found==null)throw new BusinessException(404,"Page not found");return found;}private PublicPage findPublic(String slug,String requested){String l=LOCALES.contains(requested)?requested:"zh-CN";var row=db.publicPage(slug,l);if(row==null&&!"zh-CN".equals(l))row=db.publicPage(slug,"zh-CN");if(row==null)return null;Long version=((Number)row.get("version_id")).longValue();var sections=db.sections(version).stream().filter(s->"PUBLIC".equals(s.getVisibility())&&"ACTIVE".equals(s.getStatus())).map(s->new PublicSection(s.getSectionKey(),s.getSectionType(),s.getSortOrder(),s.getPayload())).toList();return new PublicPage((String)row.get("slug"),(String)row.get("locale"),(String)row.get("title"),(String)row.get("seo_title"),(String)row.get("seo_description"),row.get("social_preview_media_id")==null?null:((Number)row.get("social_preview_media_id")).longValue(),((Number)row.get("version_no")).intValue(),(LocalDateTime)row.get("published_at"),sections);}
 private PageVersion draftOrClone(Page p,Long a){var d=db.draft(p.getId());if(d!=null)return d;var old=db.published(p.getId());need(old!=null,"No source version");d=PageVersion.builder().pageId(p.getId()).versionNo(db.maxVersion(p.getId())+1).status("DRAFT").title(old.getTitle()).seoTitle(old.getSeoTitle()).seoDescription(old.getSeoDescription()).socialPreviewMediaId(old.getSocialPreviewMediaId()).createdBy(a).updatedBy(a).build();need(db.insertVersion(d)==1,"Draft creation failed");db.cloneSections(old.getId(),d.getId());return d;}private PageView view(Page p,PageVersion v){return PageView.builder().id(p.getId()).slug(p.getSlug()).locale(p.getLocale()).title(v.getTitle()).seoTitle(v.getSeoTitle()).seoDescription(v.getSeoDescription()).socialPreviewMediaId(v.getSocialPreviewMediaId()).version(v.getVersionNo()).publishedAt(v.getPublishedAt()).sections(db.sections(v.getId())).build();}
 public List<PublicNavigation> publicNav(String l){var x=db.publicNav(LOCALES.contains(l)?l:"zh-CN");if(x.isEmpty()&&!"zh-CN".equals(l))x=db.publicNav("zh-CN");return x.stream().map(n->new PublicNavigation(n.getLabel(),n.getTargetType(),n.getTargetValue(),n.getSortOrder(),n.getOpenMode())).toList();}public List<PublicPromotion> publicPromotions(String l){var x=db.publicPromotions(LOCALES.contains(l)?l:"zh-CN",LocalDateTime.now(clock));if(x.isEmpty()&&!"zh-CN".equals(l))x=db.publicPromotions("zh-CN",LocalDateTime.now(clock));return x.stream().map(p->new PublicPromotion(p.getId(),p.getTitle(),p.getSubtitle(),p.getDescription(),p.getCoverMediaId(),p.getGalleryMediaIds(),p.getStartAt(),p.getEndAt(),p.getPriority(),p.getCtaType(),p.getCtaTarget())).toList();}public PublicLocation publicLocation(String l){var x=db.publicLocation(LOCALES.contains(l)?l:"zh-CN");if(x==null&&!"zh-CN".equals(l))x=db.publicLocation("zh-CN");return x==null?null:new PublicLocation(x.getHotelName(),x.getAddress(),x.getLatitude(),x.getLongitude(),x.getPhone(),x.getContact(),x.getDisplayMetadata());}public List<PublicScene> publicScenes(String l){var x=db.publicScenes(LOCALES.contains(l)?l:"zh-CN");if(x.isEmpty()&&!"zh-CN".equals(l))x=db.publicScenes("zh-CN");return x.stream().map(s->new PublicScene(s.getId(),s.getName(),s.getSceneType(),s.getMediaAssetId(),s.getPreviewMediaId(),s.getInteractionMode(),s.getCameraConfig())).toList();}
 public PageResult<Media> media(Integer p,Integer s){access.writer();var w=pages.window(p,s,true);return pages.result(w,db.mediaPage(w.offset(),pages.limit(w)),db.mediaCount());}@Transactional public Media upload(String type,MultipartFile f){Long a=access.writer();var z=storage.store(f,type);var m=Media.builder().assetType(type).storageKey(z.key()).publicUrl(z.url()).originalFilename(f.getOriginalFilename()).contentType(f.getContentType()).sizeBytes(z.size()).checksum(z.checksum()).status("ACTIVE").createdBy(a).build();need(db.insertMedia(m)==1,"Media registration failed");audit(a,"CMS_MEDIA_UPLOADED","Media "+m.getId());return m;}@Transactional public void archiveMedia(Long id){Long a=access.writer();need(db.media(id)!=null,"Media not found");need(db.publishedReferences(id)==0,"Published content references this media");need(db.archiveMedia(id)==1,"Media already archived");audit(a,"CMS_MEDIA_ARCHIVED","Media "+id);}
 public InternalScene internalScene(Long id){access.internal();var s=db.scene(id);need(s!=null,"Scene not found");return InternalScene.builder().scene(s).bindings(db.bindings(id)).build();}
 public Media publicMedia(String key){var m=db.mediaByKey(key);if(m==null||!"ACTIVE".equals(m.getStatus())||db.publishedReferences(m.getId())==0)throw new BusinessException(404,"Media not found");return m;}
 public PageResult<Navigation> navs(Integer p,Integer s){access.writer();var w=pages.window(p,s,true);return pages.result(w,db.navs(w.offset(),pages.limit(w)),db.navCount());}
 @Transactional public Navigation navigation(Long id,CmsRequests.NavigationWrite r){Long a=access.writer();locale(r.getLocale());need(TARGETS.contains(r.getTargetType()),"Invalid navigation target");String target=text(r.getTargetValue());if("EXTERNAL_URL".equals(r.getTargetType()))need(target!=null&&(target.startsWith("https://")||target.startsWith("http://"))&&!target.toLowerCase(Locale.ROOT).startsWith("javascript:"),"Unsafe external URL");var n=Navigation.builder().id(id).label(r.getLabel().trim()).locale(r.getLocale()).targetType(r.getTargetType()).targetValue(target).sortOrder(r.getSortOrder()).visible(r.getVisible()).openMode(r.getOpenMode()).status(r.getStatus()).createdBy(a).updatedBy(a).build();need(id==null?db.insertNav(n)==1:db.updateNav(n)==1,"Navigation write failed");audit(a,id==null?"CMS_NAV_CREATED":"CMS_NAV_UPDATED","Navigation "+n.getId());return id==null?n:db.nav(id);}
 public PageResult<Promotion> promotions(Integer p,Integer s){access.writer();var w=pages.window(p,s,true);return pages.result(w,db.promotions(w.offset(),pages.limit(w)),db.promotionCount());}
 @Transactional public Promotion promotion(Long id,CmsRequests.PromotionWrite r){Long a=access.writer();locale(r.getLocale());need(r.getStartAt()==null||r.getEndAt()==null||r.getStartAt().isBefore(r.getEndAt()),"Invalid promotion interval");if(r.getPricingPolicyId()!=null)need(db.pricingExists(r.getPricingPolicyId())==1,"Referenced pricing policy does not exist");var x=Promotion.builder().id(id).title(r.getTitle().trim()).subtitle(text(r.getSubtitle())).description(text(r.getDescription())).locale(r.getLocale()).coverMediaId(r.getCoverMediaId()).galleryMediaIds(r.getGalleryMediaIds()==null?"[]":r.getGalleryMediaIds()).startAt(r.getStartAt()).endAt(r.getEndAt()).status(r.getStatus()).priority(r.getPriority()).ctaType(r.getCtaType()).ctaTarget(text(r.getCtaTarget())).pricingPolicyId(r.getPricingPolicyId()).createdBy(a).updatedBy(a).build();validJson(x.getGalleryMediaIds());need(id==null?db.insertPromotion(x)==1:db.updatePromotion(x)==1,"Promotion write failed");audit(a,id==null?"CMS_PROMOTION_CREATED":"CMS_PROMOTION_UPDATED","Promotion "+x.getId());return id==null?x:db.promotion(id);}
 @Transactional public Location location(CmsRequests.LocationWrite r){Long a=access.writer();locale(r.getLocale());need(r.getLatitude().compareTo(new java.math.BigDecimal("-90"))>=0&&r.getLatitude().compareTo(new java.math.BigDecimal("90"))<=0&&r.getLongitude().compareTo(new java.math.BigDecimal("-180"))>=0&&r.getLongitude().compareTo(new java.math.BigDecimal("180"))<=0,"Invalid coordinates");String metadata=r.getDisplayMetadata()==null?"{}":r.getDisplayMetadata();validJson(metadata);var x=Location.builder().locale(r.getLocale()).hotelName(r.getHotelName().trim()).address(r.getAddress().trim()).latitude(r.getLatitude()).longitude(r.getLongitude()).phone(text(r.getPhone())).contact(text(r.getContact())).displayMetadata(metadata).status(r.getStatus()).createdBy(a).updatedBy(a).build();need(db.upsertLocation(x)>=1,"Location write failed");audit(a,"CMS_LOCATION_UPDATED","Location "+r.getLocale());return db.location(r.getLocale());}
 public PageResult<Scene> scenes(Integer p,Integer s){access.writer();var w=pages.window(p,s,true);return pages.result(w,db.scenes(w.offset(),pages.limit(w)),db.sceneCount());}
 @Transactional public Scene scene(Long id,CmsRequests.SceneWrite r){Long a=access.writer();locale(r.getLocale());need(Set.of("PUBLIC_ORBIT_ONLY","INTERNAL_INTERACTIVE").contains(r.getInteractionMode()),"Invalid interaction mode");need(Set.of("PUBLIC","INTERNAL").contains(r.getVisibility()),"Invalid visibility");need(!"PUBLIC".equals(r.getVisibility())||"PUBLIC_ORBIT_ONLY".equals(r.getInteractionMode()),"Public scenes must be orbit-only");var media=db.media(r.getMediaAssetId());need(media!=null&&"MODEL_3D".equals(media.getAssetType())&&"ACTIVE".equals(media.getStatus()),"Active 3D model required");String camera=r.getCameraConfig()==null?"{}":r.getCameraConfig();validJson(camera);var x=Scene.builder().id(id).name(r.getName().trim()).locale(r.getLocale()).sceneType(r.getSceneType()).mediaAssetId(r.getMediaAssetId()).previewMediaId(r.getPreviewMediaId()).visibility(r.getVisibility()).interactionMode(r.getInteractionMode()).cameraConfig(camera).status(r.getStatus()).createdBy(a).updatedBy(a).build();need(id==null?db.insertScene(x)==1:db.updateScene(x)==1,"Scene write failed");audit(a,id==null?"CMS_SCENE_CREATED":"CMS_SCENE_UPDATED","Scene "+x.getId());return id==null?x:db.scene(id);}
 @Transactional public Binding bind(Long scene,CmsRequests.BindingWrite r){Long a=access.writer();var s=db.scene(scene);need(s!=null&&"INTERNAL".equals(s.getVisibility())&&"INTERNAL_INTERACTIVE".equals(s.getInteractionMode()),"Bindings require an internal interactive scene");var b=Binding.builder().sceneId(scene).nodeKey(r.getNodeKey().trim()).floorReference(text(r.getFloorReference())).roomId(r.getRoomId()).build();need(db.insertBinding(b)==1,"Scene binding failed");audit(a,"CMS_SCENE_NODE_BOUND","Scene "+scene);return b;}
}
